void GetOAuthAccessTokenResult::set_token(
    OAuthAccessTokenPtr token) {
  if (tag_ == Tag::kToken) {
    *(data_.token) = std::move(token);
  } else {
    DestroyActive();
    tag_ = Tag::kToken;
    data_.token = new OAuthAccessTokenPtr(
        std::move(token));
  }
}

void GetOAuthAccessTokenResult::DestroyActive() {
  switch (tag_) {

    case Tag::kNone:

      delete data_.none;
      break;
    case Tag::kError:

      delete data_.error;
      break;
    case Tag::kToken:

      delete data_.token;
      break;
  }
}
size_t GetOAuthAccessTokenResult::Hash(size_t seed) const {
  seed = mojo::internal::HashCombine(seed, static_cast<uint32_t>(tag_));
  switch (tag_) {

    case Tag::kNone:
      return mojo::internal::Hash(seed, data_.none);
    case Tag::kError:
      return mojo::internal::Hash(seed, data_.error);
    case Tag::kToken:
      return mojo::internal::Hash(seed, data_.token);
    default:
      NOTREACHED();
      return seed;
  }
}

