// static
bool UnionTraits<::crosapi::mojom::GetOAuthAccessTokenResult::DataView, ::crosapi::mojom::GetOAuthAccessTokenResultPtr>::Read(
    ::crosapi::mojom::GetOAuthAccessTokenResult::DataView input,
    ::crosapi::mojom::GetOAuthAccessTokenResultPtr* output) {
  using UnionType = ::crosapi::mojom::GetOAuthAccessTokenResult;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kNone: {
      ::crosapi::mojom::OAuthNotNeededPtr result_none;
      if (!input.ReadNone(&result_none))
        return false;

      *output = UnionType::NewNone(
          std::move(result_none));
      break;
    }
    case Tag::kError: {
      ::crosapi::mojom::OAuthErrorPtr result_error;
      if (!input.ReadError(&result_error))
        return false;

      *output = UnionType::NewError(
          std::move(result_error));
      break;
    }
    case Tag::kToken: {
      ::crosapi::mojom::OAuthAccessTokenPtr result_token;
      if (!input.ReadToken(&result_token))
        return false;

      *output = UnionType::NewToken(
          std::move(result_token));
      break;
    }
    default:

      return false;
  }
  return true;
}

